1	// vsim-only handoff smoke test. Loads handoff_exit.elf, enables the hybrid
2	// handoff drain path, runs vsim, and expects:
3	//   - run() returns EXIT_HANDOFF_TO_QEMU (200)
4	//   - state.bin is written with valid magic and gpr[12] == 3
5	// The QEMU spawn half lives in the round-trip e2e test.
6	
7	#include "cpu_config.hpp"
8	#include "hybrid/state_abi.h"
9	#include "platform/platform.hpp"
10	#include "simulator.hpp"
11	
12	#include <cci_configuration>
13	#include <spdlog/sinks/stdout_color_sinks.h>
14	#include <spdlog/spdlog.h>
15	#include <systemc>
16	
17	#include <cstdio>
18	#include <cstdlib>
19	#include <fstream>
20	#include <stdexcept>
21	#include <string>
22	
23	namespace {
24	
25	template<typename Cpu>
26	auto run_smoke(const std::string& elf_path, const std::string& state_path) -> int
27	{
28	  Simulator<Cpu> sim{"sim"};
29	  sim.load_elf(elf_path);
30	
31	  sc_core::sc_start(sc_core::SC_ZERO_TIME);
32	  sim.reset();
33	  sim.enable_hybrid_handoff(elf_path, state_path);
34	
35	  spdlog::info("handoff_smoke: starting run");
36	  const auto rc = sim.run();
37	
38	  if (rc != hybrid::kExitHandoffToQemu) {
39	    spdlog::error("handoff_smoke FAIL: run() returned {} (expected {})",
40	                  rc, hybrid::kExitHandoffToQemu);
41	    return 1;
42	  }
43	
44	  std::ifstream f(state_path, std::ios::binary);
45	  if (!f) {
46	    spdlog::error("handoff_smoke FAIL: state file {} not readable",
47	                  state_path);
48	    return 2;
49	  }
50	  hybrid_state_v1 state{};
51	  f.read(reinterpret_cast<char*>(&state), sizeof(state));
52	  if (!f) {
53	    spdlog::error("handoff_smoke FAIL: short read of state file");
54	    return 3;
55	  }
56	  if (state.magic != HYBRID_STATE_MAGIC) {
57	    spdlog::error("handoff_smoke FAIL: bad magic 0x{:08x} (expected 0x{:08x})",
58	                  state.magic, HYBRID_STATE_MAGIC);
59	    return 4;
60	  }
61	  if (state.gpr[12] != 3) {
62	    spdlog::error("handoff_smoke FAIL: gpr[12] (a2) = {} (expected 3)",
63	                  state.gpr[12]);
64	    return 5;
65	  }
66	
67	  spdlog::info("handoff_smoke PASS: drained pc=0x{:x}, a2={}",
68	               state.pc, state.gpr[12]);
69	  return 0;
70	}
71	
72	}  // namespace
73	
74	extern "C" auto sc_main(int argc, char* argv[]) -> int
75	try {
76	  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
77	  spdlog::set_pattern("[%^%l%$] %v");
78	
79	  if (argc < 3) {
80	    std::fprintf(stderr, "usage: %s <elf> <state-out-path>\n", argv[0]);
81	    return EXIT_FAILURE;
82	  }
83	
84	  auto broker = cci_utils::broker{"global_broker"};
85	  cci::cci_register_broker(broker);
86	  return run_smoke<VSIM_CPU_INTERFACE_CLASS>(argv[1], argv[2]);
87	} catch (const std::exception& e) {
88	  spdlog::error("handoff_smoke FAIL: exception: {}", e.what());
89	  return 99;
90	}
